import { Block } from "@prototyp/skeletor";
import {
  EventSendState_Tags,
  type EventTimelineItem,
} from "@unomed/react-native-matrix-sdk";
import type { FC } from "react";
import { Image, StyleSheet } from "react-native";
import { Colors } from "shared/styles";

interface Props {
  event: EventTimelineItem;
}

export const DeliveryStatus: FC<Props> = ({ event }) => {
  if (!event.isOwn) return null;

  const state = event.localSendState;

  if (state?.tag === EventSendState_Tags.SendingFailed) {
    return (
      <Block
        background="transparent"
        border={{ borderRadius: 24, borderWidth: 1, borderColor: Colors.error }}
        width={18}
        height={18}
        justify="center"
        align="center"
      >
        <Image
          source={require("assets/icons/close.png")}
          style={styles.icon}
          tintColor={Colors.error}
        />
      </Block>
    );
  }

  // NotSentYet or Sent — in-flight
  if (state) {
    return (
      <Block
        background="transparent"
        border={{
          borderRadius: 24,
          borderWidth: 1,
          borderColor: Colors.white20,
        }}
        width={18}
        height={18}
      />
    );
  }

  // localSendState undefined — fully confirmed
  return (
    <Block
      background={Colors.white20}
      border={{ borderRadius: 24 }}
      width={18}
      height={18}
      justify="center"
      align="center"
    >
      <Image
        source={require("assets/icons/check.png")}
        style={styles.icon}
        tintColor={Colors.white}
      />
    </Block>
  );
};

const styles = StyleSheet.create({
  icon: {
    width: 12,
    height: 12,
  },
});

